/** `host.check`'s steps, in the order roster runs them. */
export const CHECK_STEPS = ["inventory", "ssh-config", "provider", "vault-item", "dns", "tcp", "host-key", "auth"] as const;

/** `host.verify_login`'s steps, in order. */
export const VERIFY_STEPS = ["user", "provider", "vault-item", "dns", "tcp", "host-key", "auth"] as const;

/** Changing these needs a test login that just succeeded (`host.verify_login`, decision Q43). */
export const LOGIN_FIELDS = ["ip", "user", "port", "auth"] as const;

/** Where a vault stands, in `vault.status`'s words. */
export const VAULT_STATUSES = ["locked", "unlocked", "not-logged-in", "missing-cli", "unsupported"] as const;

/** Login references with no password behind them (`prompt` has none saved either, but it's a provider of its own). */
export const NO_PASSWORD_AUTHS = ["agent", "key", "none"] as const;

/** A job's `state` (`mesh.job`, `discover.status`, `host.check_job`, `job.progress`): `running` while it runs, `over` once it's over. */
export const JOB_STATES = {
  running: ["running", "stopping"],
  over: ["done", "stopped", "failed"],
} as const;

/** `data.path` for a roster.yml path roster won't repeat (a -c value shaped like a token). */
export const PATH_NOT_REPEATED = "(not repeated)";

export type CodeName = keyof typeof Code;

// serve's params and results that are Pydantic models (src/roster/servemodels.py, decision Q113). A model of
// models.py's in one (a Host, a group) is a type parameter: the app names its own.

/** host.get's: `{name}`, or `{name, settled: true}` (API 20). */
export interface HostGetParams {
  /** The Host's exact name. */
  name: string;
  /** Wait for a write to roster.yml under way first. */
  settled?: boolean;
}

/** `hosts.list`'s `error` (API 8): why roster.yml as it is now doesn't load, while the last good Inventory is shown (catalog row 1). */
export interface InventoryError {
  /** What's wrong, with the line for a YAML error. */
  message: string;
  /** The `roster.yml` that doesn't load. */
  path: string | null;
  /** The line a YAML error is at; left out when there's none. */
  line?: number | null;
  /** What to do about it. */
  fix: string | null;
}

/** hosts.list's: every Host in roster.yml order, the groups, and `error` (API 8). */
export interface HostsListResult<Host = unknown, Group = unknown> {
  hosts: Host[];
  groups: Record<string, Group>;
  error: InventoryError | null;
}
